import{c as a,Q as t,j as o,m as n}from"./chunks/framework.B5EQ7QKW.js";const g=JSON.parse('{"title":"IPCEI-CIS Hackathon @ SAP Innovation Center Potsdam","description":"","frontmatter":{"title":"IPCEI-CIS Hackathon @ SAP Innovation Center Potsdam"},"headers":[],"relativePath":"ipcei-cis-workshop-2026/index.md","filePath":"ipcei-cis-workshop-2026/index.md","lastUpdated":1785760999000}'),r={name:"ipcei-cis-workshop-2026/index.md"};function i(s,e,l,h,c,p){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="ipcei-cis-hackathon-sap-innovation-center-potsdam" tabindex="-1">IPCEI-CIS Hackathon @ SAP Innovation Center Potsdam <a class="header-anchor" href="#ipcei-cis-hackathon-sap-innovation-center-potsdam" aria-label="Permalink to &quot;IPCEI-CIS Hackathon @ SAP Innovation Center Potsdam&quot;">​</a></h1><p>In July 2026, the Thalamus team joined a hackathon at the SAP Innovation Center in Potsdam, collaborating with contributors from the <a href="https://neonephos.org" target="_blank" rel="noreferrer">NeoNephos Foundation</a> and <a href="https://apeirora.eu" target="_blank" rel="noreferrer">ApeiroRA</a> as part of the broader <a href="https://ipcei-cis.eu" target="_blank" rel="noreferrer">IPCEI-CIS</a> initiative to develop open-source European cloud and AI infrastructure.</p><p>During the event, we worked on three concrete topics. We built a <a href="https://github.com/naira-project/naira" target="_blank" rel="noreferrer">Naira</a> plugin that feeds Thalamus model data into Naira&#39;s catalog, making it possible for Naira&#39;s MCP server to answer live questions about running inference instances. We also worked on two <a href="https://ocm.software" target="_blank" rel="noreferrer">Open Component Model (OCM)</a> topics: packaging Thalamus itself as an OCM component and distributing model weights through OCM using a Hugging Face-compatible API.</p><h2 id="naira-integration" tabindex="-1">Naira Integration <a class="header-anchor" href="#naira-integration" aria-label="Permalink to &quot;Naira Integration&quot;">​</a></h2><p>We built a <strong>Thalamus plugin for Naira</strong> that keeps Naira&#39;s AI asset catalog in sync with the models currently running in Thalamus. With the catalog populated, Naira&#39;s <strong>MCP (Model Context Protocol) server</strong> lets an MCP-capable client such as Open WebUI ask live questions about Thalamus-managed inference instances. For example, clients can ask which models are available and what engine configuration they use.</p><p><a href="/thalamus/main/ipcei-cis-workshop-2026/naira-integration">Read full post →</a></p><h2 id="ocm-packaging-thalamus-as-a-component" tabindex="-1">OCM: Packaging Thalamus as a Component <a class="header-anchor" href="#ocm-packaging-thalamus-as-a-component" aria-label="Permalink to &quot;OCM: Packaging Thalamus as a Component&quot;">​</a></h2><p>Thalamus today is installed through a set of Helm charts and configuration files bundles through a helmfile. Together with the OCM team, we explored packaging the whole Thalamus installation as a single OCM component. The goal is to turn Thalamus into a versioned, transportable artifact that can be pulled from a sovereign OCI registry and installed without relying on external tooling or manual setup. This work is still experimental and needs to mature before it can replace the current installation path.</p><p><a href="/thalamus/main/ipcei-cis-workshop-2026/ocm-packaging">Read full post →</a></p><h2 id="ocm-model-weights-as-an-ocm-component" tabindex="-1">OCM: Model Weights as an OCM Component <a class="header-anchor" href="#ocm-model-weights-as-an-ocm-component" aria-label="Permalink to &quot;OCM: Model Weights as an OCM Component&quot;">​</a></h2><p>Thalamus currently relies on external registries such as Hugging Face for model weights, which creates a dependency outside our control for a sovereign-cloud offering. We prototyped an integration with the OCM <a href="https://github.com/jakobmoellerdev/model-server" target="_blank" rel="noreferrer"><strong>model-server</strong></a> to store model weights as OCM components in an OCI registry of our choice while still exposing them through a Hugging Face-compatible API. During the hackathon we packaged a lightweight demo model, stored it in GHCR, pulled it through the model-server, and served inference from it without the weights ever touching Hugging Face.</p><p><a href="/thalamus/main/ipcei-cis-workshop-2026/ocm-model-weights">Read full post →</a></p>',12)])])}const m=a(r,[["render",i]]);export{g as __pageData,m as default};
